// Safe file storage on the local filesystem.
// - internal filenames are generated by the server (never user filenames)
// - every access path is resolved inside the configured storage root
// - uploaded files stream to disk (large-file friendly) with sha256 checksum
import { createHash, randomUUID } from "node:crypto";
import {
  createReadStream,
  createWriteStream,
  mkdirSync,
  statSync,
  rmSync,
  renameSync,
  existsSync,
} from "node:fs";
import { mkdir } from "node:fs/promises";
import path from "node:path";
import { pipeline } from "node:stream/promises";
import { Readable, Transform } from "node:stream";

export function storageRoot(): string {
  return path.resolve(process.env.STORAGE_DIR ?? "./storage/shared-files");
}

export function tmpRoot(): string {
  return path.resolve(process.env.STORAGE_TMP_DIR ?? "./storage/tmp");
}

export function ensureDirs() {
  mkdirSync(storageRoot(), { recursive: true });
  mkdirSync(tmpRoot(), { recursive: true });
}

ensureDirs();

/** A stored name is always server-generated, e.g. `ab/cd1234-uuid`. */
export function newStoredName(): { storedName: string; dir: string } {
  const hex = randomUUID().replace(/-/g, "");
  const dir = hex.slice(0, 2) + "/" + hex.slice(2, 4);
  return { storedName: `${dir}/${hex}.bin`, dir };
}

export const DEFAULT_MAX_BYTES = (() => {
  const v = Number(process.env.MAX_UPLOAD_BYTES || 2 * 1024 * 1024 * 1024);
  return Number.isFinite(v) && v > 0 ? v : 2 * 1024 * 1024 * 1024;
})();

class StorageError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "StorageError";
  }
}

/** Resolve a stored name to an absolute path, guaranteed inside the root. */
export function resolveStoredPath(storedName: string): string {
  const root = storageRoot();
  const abs = path.resolve(root, storedName);
  if (!abs.startsWith(root + path.sep)) {
    throw new StorageError("Invalid storage path");
  }
  return abs;
}

/**
 * Stream an UploadStream into a temp file, verify it stays under maxBytes,
 * compute a sha256 checksum, then atomically move it into place.
 */
export async function storeUploadedStream(
  stream: Readable,
  opts: { maxBytes?: number } = {}
): Promise<{ storedName: string; absPath: string; size: number; checksum: string }> {
  const maxBytes = opts.maxBytes ?? DEFAULT_MAX_BYTES;
  const { storedName, dir } = newStoredName();
  const finalPath = resolveStoredPath(storedName);
  const tmpPath = path.join(tmpRoot(), path.basename(finalPath) + `.${process.pid}.tmp`);

  await mkdir(path.dirname(finalPath), { recursive: true });
  mkdirSync(path.dirname(tmpPath), { recursive: true });

  const hash = createHash("sha256");
  let size = 0;
  let aborted = false;

  const counter = new Transform({
    transform(chunk, _enc, cb) {
      size += chunk.length;
      if (size > maxBytes) {
        aborted = true;
        cb(new StorageError(`Upload exceeds maximum size of ${maxBytes} bytes`));
        return;
      }
      hash.update(chunk);
      cb(null, chunk);
    },
  });

  const ws = createWriteStream(tmpPath, { flags: "wx", highWaterMark: 1024 * 1024 });
  try {
    await pipeline(stream, counter, ws);
    if (aborted) throw new StorageError("Upload exceeded maximum size");
  } catch (err) {
    try {
      rmSync(tmpPath, { force: true });
    } catch {
      /* best effort */
    }
    throw err;
  }

  const checksum = hash.digest("hex");
  renameSync(tmpPath, finalPath);
  return { storedName, absPath: finalPath, size, checksum };
}

export function fileExists(storedName: string): boolean {
  const abs = resolveStoredPath(storedName);
  return existsSync(abs);
}

export function statStoredFile(storedName: string): { absPath: string; size: number } {
  const abs = resolveStoredPath(storedName);
  if (!existsSync(abs)) throw new StorageError("File not found on disk");
  const st = statSync(abs);
  return { absPath: abs, size: st.size };
}

export function deleteStoredFile(storedName: string): void {
  const abs = resolveStoredPath(storedName);
  if (existsSync(abs)) rmSync(abs, { force: true });
}

export function readStoredStream(storedName: string): import("node:stream").Readable {
  const { absPath } = statStoredFile(storedName);
  return createReadStream(absPath);
}